/** Worker bindings. `Env` (DB, EVENTS, AUTH_MODE) is generated by
 * `wrangler types` into worker-configuration.d.ts; the secrets and the
 * test-harness switch are declared here because they are never in
 * wrangler.jsonc. */
export type Bindings = Omit<Env, "AUTH_MODE"> & {
  /** "clerk" in every deployed environment; "test" only for the feature
   * suite and local development (wrangler.jsonc documents both). */
  AUTH_MODE: "clerk" | "test";
  /** Clerk secret key - AUTH_MODE=clerk only. */
  CLERK_SECRET_KEY?: string;
  /** Comma-separated origins whose session tokens are accepted (the `azp`
   * claim), e.g. the web app's URL. Without it any frontend of the same
   * Clerk instance is trusted. */
  CLERK_AUTHORIZED_PARTIES?: string;
  /** AUTH_MODE=test only: the walker an unauthenticated request acts as, so
   * a contract-test runner that cannot send headers can still exercise the
   * fixtures. Unset, a missing token is a 401 exactly as in production. */
  TEST_DEFAULT_WALKER?: string;
};

export type AppEnv = {
  Bindings: Bindings;
  Variables: { walkerId: string };
};
